#!/usr/bin/env python3
"""Compute the benchmark GT for CSX-113_Q2 from local package files."""

from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-113"

TARGET_FAMILY = "freddy_mar12_14_rain_runoff_lag_proof"
ANSWER_LABEL = "linked_multi_day_runoff_pulse"


def read_json(relative_path: str) -> Any:
    with (PACKAGE / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def parse_time(value: str) -> datetime:
    return datetime.fromisoformat(value.replace("Z", "+00:00").replace("+00:00", ""))


def rolling_sum(values: list[float], window: int) -> list[float]:
    if len(values) < window:
        return []
    return [sum(values[index : index + window]) for index in range(len(values) - window + 1)]


def longest_wet_run(values: list[float]) -> int:
    best = 0
    current = 0
    for value in values:
        if value > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def catalog_metrics() -> dict[str, float]:
    data = read_json("data/event_catalogs/event_catalogs_001_GDACS_tropical_cyclone_event_API.json")
    freddy = None
    malawi_flood = None
    for feature in data["features"]:
        props = feature.get("properties", {})
        if props.get("eventtype") == "TC" and "FREDDY" in props.get("name", ""):
            freddy = props
        if props.get("eventtype") == "FL" and props.get("country") == "Malawi":
            malawi_flood = props
    if freddy is None or malawi_flood is None:
        raise RuntimeError("Required GDACS catalog records were not found.")

    lag_days = (parse_time(malawi_flood["fromdate"]) - parse_time(freddy["todate"])).total_seconds() / 86400
    return {
        "flood_lag_days": round(lag_days, 2),
        "gdacs_peak_wind_kmh": round(float(freddy["severitydata"]["severity"]), 1),
    }


def openmeteo_metrics() -> dict[str, float | int]:
    data = read_json("data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json")
    hourly = data["hourly"]
    times = hourly["time"]
    precip = [float(value or 0) for value in hourly["precipitation"]]
    gusts = [float(value or 0) for value in hourly["wind_gusts_10m"]]

    local_indexes = [index for index, stamp in enumerate(times) if "2023-03-12" <= stamp[:10] <= "2023-03-14"]
    wettest_24h = max(rolling_sum(precip, 24))
    wettest_72h = max(rolling_sum(precip, 72))

    return {
        "local_precip_mm": round(sum(precip[index] for index in local_indexes), 1),
        "wettest_24h_mm": round(wettest_24h, 1),
        "wettest_72h_mm": round(wettest_72h, 1),
        "wettest_24_to_72_ratio": round(wettest_24h / wettest_72h, 3),
        "wet_run_hours": longest_wet_run(precip),
        "max_gust_kmh": round(max(gusts), 1),
    }


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Local 72-hour rainfall",
                "points": 4,
                "description": "Computes 111.7 mm for both the March 12-14 local total and the maximum rolling 72-hour total.",
                "partial_credit": "Award 2 points for one correct total, or 3 points for both totals with only minor rounding or window-edge error.",
            },
            {
                "name": "Rolling ratio",
                "points": 4,
                "description": "Computes the maximum 24-hour to 72-hour precipitation ratio as 0.504.",
                "partial_credit": "Award 2 points for the correct formula with a wrong rolling numerator, or 3 points for a correct ratio rounded less precisely.",
            },
            {
                "name": "Wet-run duration",
                "points": 3,
                "description": "Computes the longest continuous wet run as 62 hours using hourly precipitation greater than 0.",
                "partial_credit": "Award 1-2 points for a continuous wet-run calculation with a minor threshold or endpoint mistake.",
            },
            {
                "name": "Catalog lag",
                "points": 3,
                "description": "Computes the Malawi flood start lag after Freddy TC end as 1.42 days.",
                "partial_credit": "Award 1-2 points for using the right timestamps but rounding or time-unit conversion incorrectly.",
            },
            {
                "name": "Gust ratio",
                "points": 3,
                "description": "Computes maximum local gust as 65.9 km/h and the local-gust to GDACS-peak-wind ratio as 0.264.",
                "partial_credit": "Award 1-2 points for one correct gust value or for a correct division with imprecise rounding.",
            },
            {
                "name": "JSON and label",
                "points": 3,
                "description": "Returns the requested JSON and the short computed consequence label linked_multi_day_runoff_pulse.",
                "partial_credit": "Award 1-2 points for the right label with missing proof details or for a correct proof but incomplete JSON.",
            },
        ],
    }


def build_gt() -> dict[str, Any]:
    catalogs = catalog_metrics()
    weather = openmeteo_metrics()
    gust_ratio = round(float(weather["max_gust_kmh"]) / catalogs["gdacs_peak_wind_kmh"], 3)
    passes = (
        weather["local_precip_mm"] >= 100
        and abs(float(weather["local_precip_mm"]) - float(weather["wettest_72h_mm"])) <= 0.05
        and weather["wettest_24_to_72_ratio"] < 0.60
        and weather["wet_run_hours"] >= 48
        and catalogs["flood_lag_days"] <= 2.0
        and gust_ratio < 0.35
    )
    label = ANSWER_LABEL if passes else "threshold_mismatch"

    proof = (
        "The March 12-14 total equals the rolling 72-hour maximum, the 24h/72h ratio is 0.504, "
        "the wet run lasts 62 hours, the flood lag is 1.42 days, and the gust ratio is 0.264, "
        "so all thresholds pass."
    )
    primary_gt = {
        "answer": {
            "local_precip_mm": weather["local_precip_mm"],
            "wettest_72h_mm": weather["wettest_72h_mm"],
            "wettest_24_to_72_ratio": weather["wettest_24_to_72_ratio"],
            "wet_run_hours": weather["wet_run_hours"],
            "flood_lag_days": catalogs["flood_lag_days"],
            "max_gust_kmh": weather["max_gust_kmh"],
            "gust_to_peak_wind_ratio": gust_ratio,
            "consequence_label": label,
        },
        "proof": proof,
    }

    return {
        "schema_version": "1.0",
        "task_id": "CSX-113_Q2",
        "event_id": "CSX-113",
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "wettest_24h_mm": weather["wettest_24h_mm"],
            "gdacs_peak_wind_kmh": catalogs["gdacs_peak_wind_kmh"],
            "timestamp_basis": "package hourly timestamps for the rain/gust window; GDACS catalog UTC timestamps for flood lag",
            "thresholds": {
                "local_precip_mm_min": 100.0,
                "local_equals_72h_tolerance_mm": 0.05,
                "wettest_24_to_72_ratio_max": 0.60,
                "wet_run_hours_min": 48,
                "flood_lag_days_max": 2.0,
                "gust_to_peak_wind_ratio_max": 0.35,
            },
        },
        "thresholds": {
            "local_precip_mm_min": 100.0,
            "local_equals_72h_tolerance_mm": 0.05,
            "wettest_24_to_72_ratio_max": 0.60,
            "wet_run_hours_min": 48,
            "flood_lag_days_max": 2.0,
            "gust_to_peak_wind_ratio_max": 0.35,
        },
        "derived": {
            "target_family": TARGET_FAMILY,
            "wettest_24h_mm": weather["wettest_24h_mm"],
            "gdacs_peak_wind_kmh": catalogs["gdacs_peak_wind_kmh"],
            "consequence_label": label,
            "proof": proof,
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "data/event_catalogs/event_catalogs_001_GDACS_tropical_cyclone_event_API.json",
                "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json",
            ],
        },
    }


if __name__ == "__main__":
    output = TASK_DIR / "computed_gt.json"
    output.write_text(json.dumps(build_gt(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")
